begin;

do $$
declare
  v_sector uuid;
  v_category uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_category from public.categories where slug='addiction-prevention-early-intervention' and sector_id=v_sector;
  if v_sector is null or v_category is null then raise exception 'prevention taxonomy missing'; end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','الوقاية من اضطرابات استخدام المواد لا تبدأ بمحاضرة عن المخدرات ولا تنتهي بطلب الامتناع. الوقاية الفعالة تبني ظروفًا تقلل احتمال بدء الاستخدام الضار أو تطوره، وتزيد عوامل الحماية عبر مراحل النمو والأسرة والمدرسة والمجتمع والسياسات، وتلتقط المشكلات مبكرًا قبل أن تتحول إلى اضطراب أكثر شدة. المعايير الدولية الصادرة عن مكتب الأمم المتحدة المعني بالمخدرات والجريمة ومنظمة الصحة العالمية ترتب التدخلات بحسب العمر والبيئة وتؤكد أن قوة الوقاية تأتي من نظام مترابط لا من نشاط منفرد. لهذا يعرض هذا المرجع ما تدعمه الأدلة، وما يحتاج تكييفًا محليًا، وكيف نقيس النتائج بدل الاكتفاء بعدد المحاضرات أو المنشورات.'),

    jsonb_build_object('type','heading','level',2,'text','1. الوقاية نظام نمائي وليست حملة موسمية'),
    jsonb_build_object('type','paragraph','text','خطر استخدام المواد لا ينشأ من عامل واحد. يتأثر بالتطور العصبي والنفسي، الصحة النفسية، العلاقات الأسرية، الأقران، المدرسة، فرص التعليم والعمل، الصدمات والضغط، توفر المواد وتسويقها، الأعراف الاجتماعية، وجود خدمات مبكرة، والفقر أو التهميش أو عدم الاستقرار. وجود عامل خطر لا يعني أن الشخص سيستخدم المواد حتمًا، ووجود عامل حماية واحد لا يضمن المنع. الوقاية الجيدة تجمع عوامل قابلة للتعديل وتعمل عليها في الوقت المناسب، مع تجنب وصم الأطفال أو الأسر بوصفهم حالات متوقعة للإدمان.'),
    jsonb_build_object('type','paragraph','text','تتغير الأولويات عبر العمر. في الطفولة المبكرة يكون دعم النمو والرعاية الوالدية والبيئة الآمنة أكثر أهمية من تقديم معلومات تفصيلية عن مواد لم يعرفها الطفل بعد. في سنوات المدرسة تصبح المهارات الاجتماعية والتنظيم الانفعالي والانتماء المدرسي وحل المشكلات والعلاقات مع الأقران أكثر حضورًا. في المراهقة تزداد أهمية الاستقلال والهوية والضغط الاجتماعي والاتصال الرقمي والوصول إلى المنتجات. وفي البالغين قد تصبح بيئة العمل والألم والأدوية والصحة النفسية والضغوط الاقتصادية عوامل مهمة. الوقاية لذلك سلسلة مستمرة، لا درسًا موحدًا لكل الأعمار.'),

    jsonb_build_object('type','heading','level',3,'text','الوقاية الشاملة والانتقائية والموجهة'),
    jsonb_build_object('type','paragraph','text','يمكن تنظيم الوقاية إلى مستويات تساعد في اختيار التدخل. الوقاية الشاملة تستهدف جميع أفراد مجموعة أو مجتمع، مثل تحسين المناخ المدرسي أو سياسات الحد من التسويق والوصول. الوقاية الانتقائية تركز على مجموعات ترتفع لديها عوامل خطر معروفة، مثل شباب في سياقات اجتماعية شديدة الهشاشة، مع تجنب تحويل الانتماء إلى المجموعة إلى تشخيص. الوقاية الموجهة تستهدف أشخاصًا ظهرت لديهم مؤشرات أو سلوكيات مبكرة تستدعي تدخلاً أكثر تخصيصًا دون افتراض وجود اضطراب كامل. هذا التقسيم يساعد في مطابقة كثافة الخدمة مع الحاجة ويمنع الإفراط في التدخل أو تأخره.'),

    jsonb_build_object('type','heading','level',2,'text','2. ما الذي نبنيه قبل الحديث عن المواد؟'),
    jsonb_build_object('type','paragraph','text','في المراحل المبكرة تركز الوقاية على القدرات التي تجعل الطفل أو اليافع أكثر قدرة على التعامل مع الضغط واتخاذ القرار وطلب المساعدة. الرعاية المستجيبة، الروتين المتوقع، المهارات الوالدية، الدعم العاطفي، الانتماء إلى المدرسة، مهارات التواصل وحل المشكلات، والفرص الآمنة للمشاركة كلها مكونات يمكن أن تعمل كعوامل حماية. لا يعني ذلك أن المهارات الحياتية وحدها تمنع كل استخدام؛ قيمتها تكون أعلى عندما تُدرج داخل بيئة أسرية ومدرسية ومجتمعية داعمة.'),
    jsonb_build_object('type','paragraph','text','من المهم كذلك عدم تحويل الوقاية إلى مراقبة دائمة للطفل. الثقة والحدود الواضحة والتوقعات المناسبة للعمر أكثر اتزانًا من أسلوب يقوم على الاشتباه المستمر أو العقوبات غير المتناسبة. عندما يعترف اليافع بتجربة أو ضغط من الأقران، الهدف الأول هو فهم السياق ومستوى الخطر والحفاظ على باب التواصل. الاستجابة التي تجعل الإفصاح مكلفًا جدًا قد تدفع السلوك إلى السرية وتمنع الأسرة من معرفة تغيرات مهمة في الصحة أو العلاقات أو المدرسة.'),

    jsonb_build_object('type','heading','level',2,'text','3. الأسرة: مهارات قابلة للتعلم وليست لومًا للوالدين'),
    jsonb_build_object('type','heading','level',3,'text','المتابعة الداعمة والحدود والتواصل'),
    jsonb_build_object('type','paragraph','text','برامج المهارات الأسرية المدروسة لا تقوم على إلقاء اللوم على الوالدين. هي تدرب على ممارسات محددة: توقعات واضحة ومناسبة للعمر، متابعة مكان الطفل وأنشطته بصورة معقولة، تعزيز السلوك الإيجابي، تواصل هادئ، حل النزاع، معرفة الأصدقاء والروتين، واتساق القواعد بين مقدمي الرعاية قدر الإمكان. تحديث UNODC لعام 2025 لبرامج المهارات الأسرية يعرض نماذج اختبرت هذه العناصر في سياقات مختلفة. المهم ليس نسخ برنامج باسمه، بل الحفاظ على المكونات الفعالة وتكييف اللغة والأمثلة والثقافة والموارد.'),
    jsonb_build_object('type','paragraph','text','إذا كانت الأسرة تواجه عنفًا أو اضطرابًا نفسيًا شديدًا أو استخدام مواد لدى أحد مقدمي الرعاية أو فقرًا حادًا، فقد لا تكفي جلسة مهارات عامة. ينبغي ربط الوقاية بخدمات أوسع تعالج الأمان والصحة النفسية والحماية الاجتماعية. كما يجب ألا تُستخدم الأسرة كذريعة لإخفاء مسؤولية البيئة والسياسات؛ حتى الوالد المتابع جيدًا يعمل داخل سوق وتسويق ومدرسة ومجتمع يمكن أن يزيد أو يقلل التعرض. الوقاية الأسرية جزء من منظومة، لا بديل عنها.'),
    jsonb_build_object('type','paragraph','text','الحوار عن المواد يصبح أكثر فائدة عندما يناسب العمر ويجيب عن الأسئلة الواقعية دون تهويل أو تفاصيل تثير الفضول بلا حاجة. يمكن الحديث عن اتخاذ القرار، الضغط الاجتماعي، المنتجات القانونية وغير القانونية، وكيفية طلب المساعدة، مع توضيح قواعد الأسرة وأسبابها. إذا كان اليافع قد بدأ الاستخدام، يتحول الحوار من الوقاية الأولية إلى تقييم مبكر: ما المادة؟ كم تغير الأداء أو النوم أو المزاج؟ هل توجد قيادة أو حوادث أو فقدان وعي أو أدوية أخرى؟ وهل يلزم مختص؟ الهدف حماية العلاقة والوصول إلى خدمة مناسبة.'),

    jsonb_build_object('type','heading','level',2,'text','4. المدرسة: مناخ ومهارات وسياسات، لا محاضرة خوف واحدة'),
    jsonb_build_object('type','heading','level',3,'text','التعليم التفاعلي والمهارات الاجتماعية'),
    jsonb_build_object('type','paragraph','text','تصف المعايير الدولية برامج مدرسية أكثر فائدة عندما تكون منظمة وتفاعلية وتدرب على مهارات شخصية واجتماعية مثل اتخاذ القرار والتعامل مع الضغط والتواصل ومقاومة تأثير الأقران، بدل الاكتفاء بنقل معلومات. يتعلم الطلاب أكثر عندما يمارسون المهارة ويناقشون مواقف واقعية ويعود البرنامج عبر جلسات مناسبة للعمر. المحتوى يحتاج مدربين أو معلمين مؤهلين ودليل تنفيذ واضحًا، لأن اسم البرنامج وحده لا يضمن الجودة إذا تغيرت مكوناته الأساسية أو تحول إلى عرض سريع.'),
    jsonb_build_object('type','paragraph','text','المناخ المدرسي نفسه تدخل وقائي. الشعور بالأمان والانتماء، علاقات محترمة مع البالغين، قواعد سلوكية واضحة وعادلة، معالجة التنمر، فرص مشاركة الطالب، ودعم من يتراجع حضوره أو تحصيله يمكن أن تقلل مسارات خطر متعددة في الوقت نفسه. الطالب الذي يتغيب كثيرًا أو ينسحب اجتماعيًا لا ينبغي أن يُصنف مباشرة على أنه يستخدم مواد؛ هذه إشارات تحتاج فهمًا أوسع للصحة النفسية والأسرة والتعلم والضغط قبل اختيار الاستجابة.'),
    jsonb_build_object('type','paragraph','text','السياسة المدرسية ينبغي أن تفرق بين الحماية والعقوبة. وجود مادة أو استخدام داخل المدرسة قد يحتاج إجراءات سلامة وقانونًا محليًا، لكن الطرد وحده قد يزيد الانقطاع والعزلة لدى بعض الطلاب. النظام المتوازن يحدد المخالفات، يحمي بقية الطلاب، ويملك في الوقت نفسه مسارًا لتقييم الحاجة إلى دعم نفسي أو أسري أو علاج متخصص. كما ينبغي حماية السرية ضمن حدود القانون وتجنب الإعلان عن حالات الطلاب أو تحويل قصصهم إلى مادة توعوية دون موافقة مناسبة.'),

    jsonb_build_object('type','heading','level',2,'text','5. لماذا لا تكفي حملات التخويف والمعلومات وحدها؟'),
    jsonb_build_object('type','paragraph','text','المعلومة الصحيحة مهمة، لكن الوقاية لا تصبح فعالة لمجرد أن الرسالة تصف أخطار المواد. مواد UNODC الموجهة للشباب والمعايير الدولية تشير إلى أن الرسائل المثيرة للخوف أو الصور الانفعالية والمحتوى الذي يكتفي بسرد الأضرار قد يكون غير مقنع أو يخلق مقاومة أو وصمة، خصوصًا إذا تعارض مع تجارب الشباب الواقعية. كما أن تقديم تفاصيل مبكرة جدًا عن مواد غير معروفة للطفل قد يرفع الفضول بدل أن يبني حماية. لذلك يجب أن يكون الاتصال جزءًا من استراتيجية أوسع لهدف محدد وجمهور محدد ومهارات وخدمات يمكن الوصول إليها.'),
    jsonb_build_object('type','paragraph','text','الحملة الأفضل تحدد ماذا تريد أن يتغير: هل الهدف تصحيح تصور أن الجميع يستخدمون مادة؟ أم تقوية قدرة اليافع على رفض ضغط اجتماعي؟ أم توجيه الأسرة إلى خدمة مبكرة؟ أم تقليل تعرض الأطفال لتسويق منتج؟ ثم تختبر الرسائل مع الجمهور وتراقب الوصول والفهم والتأثير غير المقصود. رسالة واسعة جدًا مثل المخدرات تدمر الحياة لا تخبر الشخص بما يستطيع فعله الآن ولا تميز بين الوقاية والعلاج ولا تقدم مسار مساعدة.'),
    jsonb_build_object('type','paragraph','text','الشهادات الشخصية يمكن أن تدعم الفهم والتعاطف، لكنها لا تتحول تلقائيًا إلى تدخل وقائي مثبت. قصة واحدة لا تمثل كل المسارات، وقد تحمل تفاصيل غير مناسبة أو تصور التعافي بوصفه نتيجة إرادة فردية فقط. إذا استُخدمت الخبرة المعيشة، ينبغي أن تكون ضمن أهداف واضحة وحماية للخصوصية وتدريب ودعم للمشارك، وأن ترتبط بمهارة أو خدمة أو تغيير بيئي قابل للقياس.'),

    jsonb_build_object('type','heading','level',2,'text','6. المجتمع والسياسات: الوقاية لا تقع على الطفل وحده'),
    jsonb_build_object('type','paragraph','text','تؤثر سهولة الوصول والأسعار والتسويق والأعراف والفرص الترفيهية والسلامة والبيئة الرقمية في احتمالات الاستخدام والضرر. لهذا تتضمن الوقاية الفعالة أدوات سكانية إلى جانب برامج الأفراد. في الكحول، يعرض إطار WHO SAFER تدخلات عالية الجدوى تشمل تنظيم التوفر، إجراءات القيادة تحت التأثير، الفحص والتدخل المختصر والعلاج، القيود الشاملة على الإعلان والترويج والرعاية، وسياسات الأسعار والضرائب حيث تنطبق قانونيًا. تقرير WHO الصادر في يونيو 2026 يؤكد أهمية تحويل هذه الأدوات إلى تنفيذ ومراقبة مستمرة.'),
    jsonb_build_object('type','paragraph','text','في التبغ والنيكوتين، يوفر WHO FCTC وحزمة MPOWER إطارًا سكانيًا يشمل مراقبة الاستخدام، حماية الناس من الدخان، إتاحة المساعدة على الإقلاع، تقديم معلومات صحية فعالة، حظر الإعلان والترويج والرعاية، ورفع الضرائب. التطورات الحديثة في أكياس النيكوتين والمنتجات الإلكترونية والتسويق عبر المؤثرين والألعاب والمنصات تعني أن الوقاية تحتاج مراقبة مستمرة للسوق لا قائمة منتجات ثابتة. WHO حذرت في 2026 من أساليب تسويق تستهدف الشباب عبر النكهات والتصميم والرعاية والمحتوى الرقمي.'),
    jsonb_build_object('type','paragraph','text','السياسات السكانية لا تُنسخ حرفيًا بين البلدان. القانون والثقافة والسوق غير الرسمي والضرائب والقدرة على الإنفاذ تختلف. لكن المبدأ ثابت: إذا كان النظام يطلب من الطفل مقاومة منتج متاح بكثافة ومسوق باستمرار ورخيص نسبيًا، فهو يضع عبء الوقاية على الطرف الأضعف. التصميم الجيد يوازن بين المهارات الفردية والبيئة التي تشكل الاختيارات.'),

    jsonb_build_object('type','heading','level',3,'text','البيئة الرقمية والتسويق الجديد'),
    jsonb_build_object('type','paragraph','text','المنصات الرقمية تجمع الإعلانات والترفيه والأقران والمؤثرين والتجارة في مساحة واحدة، ما يجعل الفصل بين المحتوى العضوي والتسويق أصعب. الوقاية الرقمية لا تعني منع الإنترنت؛ تشمل محو الأمية الإعلامية، فهم أساليب التأثير، قواعد أسرية واقعية، أدوات منصات مناسبة للعمر، ورقابة تنظيمية على التسويق عندما ينطبق القانون. كما يجب على البرامج مراقبة المنصات والمنتجات التي يستخدمها جمهورها بالفعل بدل بناء رسائلها على افتراضات قديمة.'),

    jsonb_build_object('type','heading','level',2,'text','7. التدخل المبكر: عندما تظهر إشارات قبل أن تتفاقم المشكلة'),
    jsonb_build_object('type','paragraph','text','التدخل المبكر يقع بين الوقاية العامة وعلاج الاضطراب الأكثر شدة. قد يبدأ عندما يظهر استخدام متكرر، تراجع وظيفي، مشاكل أسرية أو مدرسية مرتبطة بالاستخدام، إصابات، قيادة خطرة، أعراض نفسية، أو قلق صريح من الشخص أو الأسرة. لا توجد علامة واحدة تشخص اضطرابًا بمفردها. لذلك يبدأ المسار بحوار غير وصمي وتقييم منظم يناسب العمر والسياق، ويبحث أيضًا عن الصحة النفسية والعنف والأدوية والألم والنوم واستخدام أكثر من مادة.'),
    jsonb_build_object('type','paragraph','text','في الرعاية الصحية، تدعم أطر WHO مثل SAFER الوصول إلى الفحص والتدخلات المختصرة والعلاج في الكحول، بينما يمكن استخدام أدوات فحص معتمدة ضمن تدريب مناسب في سياقات أخرى. الفحص ليس تشخيصًا ولا ينبغي استخدام درجته منفردة لفرض عقوبة. وظيفته اكتشاف من قد يحتاج حوارًا أعمق أو تقييمًا أو إحالة. يجب أن يعرف النظام ماذا سيفعل بالنتيجة قبل إطلاق فحص واسع؛ اكتشاف الخطر دون وجود مسار متابعة قد يزيد القلق دون فائدة.'),
    jsonb_build_object('type','paragraph','text','التدخل المختصر الجيد يربط النتيجة بهدف واقعي واتفاق على خطوة تالية ومراجعة. قد يكون ذلك تقليل موقف خطر، تحسين النوم، العودة لموعد، إشراك شخص داعم بموافقة مناسبة، أو إحالة إلى خدمة متخصصة. إذا ظهرت علامات اعتماد أو انسحاب أو جرعة زائدة أو اضطراب نفسي شديد أو خطر إيذاء النفس، ينتقل المسار إلى تقييم وعلاج أكثر كثافة بدل الاستمرار في نموذج وقائي عام.'),

    jsonb_build_object('type','heading','level',2,'text','8. الفئات التي تحتاج وقاية مصممة لا وصمة إضافية'),
    jsonb_build_object('type','heading','level',3,'text','الصدمة والتشرد والاحتياجات الخاصة والهشاشة الاجتماعية'),
    jsonb_build_object('type','paragraph','text','الأطفال واليافعون الذين تعرضوا للعنف أو النزوح أو فقدان مقدم رعاية أو التشرد أو الاستبعاد المدرسي قد يحملون عوامل خطر أعلى، لكن تصنيفهم كمستقبلين محتملين للإدمان يضيف وصمة ولا يقدم خدمة. الوقاية المراعية للصدمة تركز على الأمان والعلاقات والتنظيم الانفعالي والخدمات النفسية والاجتماعية والاستقرار، وتجنب الأساليب التي تعيد الإذلال أو تفترض أن السلوك تحد متعمد. إذا كان السكن أو الغذاء أو الأمان غير مستقر، فقد تكون هذه الاحتياجات جزءًا مباشرًا من خطة الوقاية.'),
    jsonb_build_object('type','paragraph','text','ذوو الاحتياجات الخاصة قد يحتاجون لغة سهلة القراءة، صورًا أو تواصلًا بديلًا، وقتًا إضافيًا، محتوى حسيًا مناسبًا، وتدريبًا لمن يقدم البرنامج. ينبغي مراجعة ما إذا كانت أداة الفحص أو المادة التعليمية اختُبرت مع الفئة المقصودة؛ ترجمة الكلمات وحدها لا تجعل الأداة صالحة ثقافيًا أو معرفيًا. كما يحتاج مقدمو الرعاية إلى معلومات تحمي الاستقلال وتقلل الاستغلال دون تحويل الحماية إلى سيطرة مطلقة.'),
    jsonb_build_object('type','paragraph','text','الجنس والعمر والثقافة والسياق القانوني تؤثر في الوصول. فتاة تخشى العقوبة الأسرية أو شخص يخشى فقدان العمل أو مهاجر لا يفهم نظام الخدمة قد يتجنب طلب المساعدة حتى لو عرف المخاطر. لذلك تقيس الوقاية الفعالة من يصل ومن لا يصل، وتبحث عن الفروق في الإحالة والاستمرار والنتائج، ثم تعدل نقطة الوصول واللغة والخصوصية والوقت والمكان.'),

    jsonb_build_object('type','heading','level',2,'text','9. الأدوية الموصوفة والمنتجات المنزلية: الوقاية تبدأ من النظام'),
    jsonb_build_object('type','paragraph','text','بعض مخاطر الاستخدام تبدأ من أدوية موصوفة أو مخزنة في المنزل. الوقاية هنا لا تعني أن المريض يتجنب علاجًا يحتاجه، بل أن الوصف والمتابعة والتخزين والتخلص والتثقيف تتم بطريقة تقلل الاستخدام غير المقصود أو مشاركة الدواء أو الوصول غير المناسب. يجب على المريض اتباع تعليمات مقدم الرعاية والصيدلي وعدم تغيير الجرعات أو إيقاف أدوية قد تسبب انسحابًا بصورة ذاتية. ويمكن للأسرة مراجعة الأدوية الموجودة ومعرفة أيها يحتاج حفظًا خاصًا أو إعادة إلى قناة تخلص معتمدة محليًا.'),
    jsonb_build_object('type','paragraph','text','الرسالة المؤسسية الأهم هي أن الوقاية ليست مسؤولية المريض وحده. أنظمة الوصف والصرف والمتابعة، تدريب مقدمي الرعاية، مشاركة المعلومات الضرورية، واكتشاف الاستخدام المتعدد للأدوية كلها تقلل المخاطر. إذا كان الشخص يعاني ألمًا أو اضطراب نوم أو قلقًا، فالتعامل مع السبب وخطة المتابعة أكثر فائدة من وصم طلب الدواء. كما ينبغي توعية الأسر بأن المنتجات القانونية مثل الكحول والنيكوتين والأدوية قد تحمل مخاطر اعتماد وضرر ولا تصبح منخفضة الخطر لمجرد قانونيتها.'),

    jsonb_build_object('type','heading','level',2,'text','10. كيف نبني برنامج وقاية مؤسسيًا؟'),
    jsonb_build_object('type','paragraph','text','يبدأ البرنامج بتحديد المشكلة والسكان والمرحلة العمرية والبيئة، ثم مراجعة البيانات المتاحة بدل البدء بنشاط مفضل مسبقًا. ما نسبة الاستخدام أو المؤشرات المبكرة؟ أين تظهر الفجوات؟ ما عوامل الحماية الموجودة؟ من لا تصل إليه الخدمات؟ بعد ذلك تُختار تدخلات تتوافق مع الأدلة والموارد ويُحدد ما يجب الحفاظ عليه عند التكييف. يجب توثيق النظرية التي تربط النشاط بالنتيجة: لماذا نتوقع أن يؤدي تدريب مهارة أو تغيير سياسة أو دعم أسرة إلى أثر محدد؟'),
    jsonb_build_object('type','paragraph','text','التنفيذ يحتاج تدريبًا وإشرافًا ومواد مناسبة وجدولاً واقعيًا وإدارة بيانات وحماية خصوصية وخطة إحالة. إذا كان البرنامج مدرسيًا، يحتاج تنسيقًا مع الإدارة والمرشدين والمعلمين والأسر والجهات الصحية. إذا كان مجتمعيًا، يحتاج مشاركة الشباب والمجتمع لا مجرد استشارتهم بعد اكتمال التصميم. وإذا كان سياسة سكانية، يحتاج جهة مسؤولة عن الإنفاذ وبيانات التزام وتأثير. كل مسار يحتاج مسؤولية محددة؛ عبارة نتعاون مع الجهات لا تكفي لتحديد من يفعل ماذا عندما تظهر حالة تحتاج متابعة.'),
    jsonb_build_object('type','paragraph','text','التكييف المحلي مشروع عندما يحافظ على الوظائف الأساسية للتدخل. يمكن تغيير الأمثلة والأسماء واللغة وطريقة تقديم النشاط لتناسب الثقافة والوصول، لكن حذف جلسات التمرين أو تقليل البرنامج إلى محاضرة قد يغير الآلية نفسها. لهذا تُسجل التعديلات ويُقاس الالتزام بالمكونات الرئيسية إلى جانب رضا المشاركين. البرنامج المحبوب ليس بالضرورة فعالًا، والبرنامج الفعال في دراسة واحدة ليس مضمونًا في بيئة مختلفة دون تنفيذ جيد.'),

    jsonb_build_object('type','heading','level',2,'text','11. القياس: هل منعنا الضرر أم فقط نفذنا أنشطة؟'),
    jsonb_build_object('type','paragraph','text','عدد الحضور والمنشورات والجلسات مؤشرات تنفيذ، وليست نتائج وقائية كافية. بحسب هدف البرنامج يمكن قياس بدء الاستخدام، العمر عند البدء، الاستخدام الحديث أو المتكرر، نوبات الاستخدام عالي الخطر، الإصابات، التوجهات والمعايير الاجتماعية، مهارات الرفض واتخاذ القرار، المناخ المدرسي، الحضور والانتماء، تواصل الأسرة، الوصول إلى التدخل المبكر، أو مؤشرات سكانية مثل التعرض للتسويق والتوفر. يجب اختيار عدد محدود من النتائج المهمة قبل بدء البرنامج وتحديد متى وكيف ستقاس.'),
    jsonb_build_object('type','paragraph','text','التقييم يحتاج مجموعة أساس ومتابعة مناسبة، وأحيانًا تصميمًا مقارنًا عندما يكون ممكنًا وأخلاقيًا. ينبغي فصل أثر البرنامج عن تغيرات السوق أو القوانين أو أحداث المجتمع. كما يجب تسجيل من انسحب ومن لم يشارك، لأن تقييم من أكمل فقط قد يعطي صورة متفائلة. البيانات النوعية من الطلاب والأسر والمنفذين تساعد في تفسير الأرقام: قد يفشل البرنامج لأن وقته غير مناسب أو لأن المحتوى لا يشبه واقع الجمهور أو لأن الإحالة غير متاحة.'),
    jsonb_build_object('type','paragraph','text','العدالة جزء من القياس. إذا تحسن المتوسط بينما بقيت فئة معينة دون وصول أو ازدادت الفجوة، فالمشكلة لم تُحل بالكامل. يمكن تفكيك النتائج حسب العمر والجنس والمنطقة ونوع المدرسة أو مؤشرات اجتماعية مناسبة مع حماية الخصوصية، ثم مراجعة الحواجز. لا ينبغي جمع بيانات حساسة لمجرد أنها متاحة؛ كل متغير يحتاج سببًا واضحًا واستخدامًا محددًا وحماية مناسبة.'),

    jsonb_build_object('type','heading','level',2,'text','12. خريطة قرار: من الوقاية العامة إلى العلاج دون فجوات'),
    jsonb_build_object('type','paragraph','text','إذا لم توجد مؤشرات استخدام، ركز على البيئة والمهارات والعلاقات والسياسات المناسبة للعمر. إذا ظهرت عوامل خطر مرتفعة دون استخدام واضح، أضف دعمًا انتقائيًا يعالج العامل نفسه مثل الصحة النفسية أو الانقطاع المدرسي أو الأسرة. إذا بدأ استخدام أو ظهر ضرر مبكر، انتقل إلى تقييم وتدخل مختصر أو خدمة متخصصة بحسب الشدة. إذا وجدت علامات انسحاب أو جرعة زائدة أو اعتماد أو اضطراب نفسي خطير، فهذه لم تعد مسألة برنامج وقائي عام؛ يحتاج الشخص مسار علاج وسلامة مناسبًا مع استمرار دعم الأسرة والمدرسة والمجتمع.'),
    jsonb_build_object('type','paragraph','text','النجاح هو أن تكون الحدود بين هذه المراحل قابلة للحركة. لا ينبغي أن يضيع الشخص لأن برنامج الوقاية لا يعالج، أو لأن خدمة العلاج لا تستقبل من لم يصل بعد إلى شدة معينة. نظام الإحالة يحدد معايير الانتقال والجهة التالية والوقت المتوقع ومن يتأكد من الوصول. وبعد العلاج، تعود بعض عناصر الوقاية في صورة حماية من العودة للضرر ودعم الأسرة والمدرسة والعمل والبيئة. بهذا يصبح القطاع سلسلة واحدة من الوقاية إلى التدخل المبكر إلى العلاج والتعافي.'),
    jsonb_build_object('type','paragraph','text','المرجع العربي القوي لا يَعِد بمنع كل اضطراب ولا يحول عوامل الخطر إلى تنبؤات فردية. يقدم خيارات ذات أساس علمي، يوضح مستوى الدليل وحدوده، ويربط المستخدم بالخطوة المناسبة. كما يراجع المحتوى دوريًا لأن المنتجات والأسواق والتسويق والمنصات والسياسات تتغير أسرع من كثير من المناهج التقليدية. ما يبقى ثابتًا هو مبدأ الوقاية المبنية على النمو والبيئة والمهارات والحقوق والقياس، لا الخوف والوصم.'),

    jsonb_build_object('type','faq','items',jsonb_build_array(
      jsonb_build_object('question','ما أفضل طريقة للوقاية من الإدمان لدى المراهقين؟','answer','لا توجد طريقة منفردة. أفضل نهج يجمع أسرة داعمة وحدودًا واضحة، مناخًا مدرسيًا جيدًا، مهارات اجتماعية وانفعالية، معلومات مناسبة للعمر، تقليل التعرض والتوفر حيث تنطبق السياسات، واكتشافًا مبكرًا للمشكلات النفسية أو السلوكية مع مسار مساعدة واضح.'),
      jsonb_build_object('question','هل تخويف الأطفال من المخدرات يمنع الاستخدام؟','answer','المعلومات عن المخاطر مهمة، لكن التخويف أو الصور الانفعالية وحدها لا تمثل وقاية فعالة وقد تكون غير مقنعة أو تزيد الوصمة أو المقاومة. الرسائل الأفضل ترتبط بالعمر والمهارات والسياق وخدمات يمكن الوصول إليها، وتكون جزءًا من برنامج أوسع.'),
      jsonb_build_object('question','متى أبدأ الحديث مع طفلي عن المواد؟','answer','ابدأ بالمفاهيم المناسبة للعمر مثل السلامة والأدوية واتخاذ القرار وطلب المساعدة قبل الحاجة إلى تفاصيل عن مواد محددة. مع زيادة العمر والتعرض يمكن توسيع الحوار بلغة واقعية وواضحة. الهدف بناء علاقة تسمح بالسؤال والإفصاح، لا تقديم كمية معلومات أكبر من الحاجة.'),
      jsonb_build_object('question','هل فحص تعاطي المواد في المدرسة فكرة جيدة؟','answer','أي فحص يحتاج غرضًا واضحًا وأداة مناسبة وخصوصية ومسار متابعة وقواعد قانونية وأخلاقية. الفحص ليس تشخيصًا ولا ينبغي أن يصبح أداة عقوبة تلقائية. غالبًا يكون دعم المناخ المدرسي والتقييم المهني عند وجود مؤشرات أكثر اتزانًا من فحص غير مرتبط بخدمة.'),
      jsonb_build_object('question','ما علامات الحاجة إلى تدخل مبكر؟','answer','تغير متكرر مرتبط بالاستخدام مثل تراجع الوظيفة أو الدراسة، حوادث، صراعات، استخدام متزايد، مشاكل نوم أو مزاج، استخدام مواد متعددة أو قلق الشخص نفسه قد يستدعي تقييمًا. لا تشخص علامة واحدة اضطرابًا؛ يُفهم النمط والسياق ويُحدد مستوى الخدمة المناسب.'),
      jsonb_build_object('question','هل العقوبة تمنع المراهق من العودة إلى الاستخدام؟','answer','الحدود والعواقب المناسبة قد تكون جزءًا من التربية أو سياسة المدرسة، لكن العقوبة وحدها لا تعالج الدوافع أو الضغط أو الصحة النفسية أو الاعتماد. الاستجابة الأفضل تحمي السلامة وتحافظ على قواعد واضحة وتضيف تقييمًا ودعمًا وعلاجًا عند الحاجة.'),
      jsonb_build_object('question','كيف أعرف أن برنامج الوقاية في المدرسة جيد؟','answer','ابحث عن برنامج مناسب للعمر، تفاعلي، يدرب مهارات محددة، ينفذه أشخاص مدربون، يمتد بما يكفي للممارسة، يرتبط بمناخ مدرسي وسياسة إحالة، ويقيس نتائج فعلية لا الحضور والرضا فقط. يجب أيضًا توثيق أي تكييف للمحتوى ومراجعة أثره.'),
      jsonb_build_object('question','ما دور السياسات في الوقاية إذا كان القرار فرديًا؟','answer','القرارات تتأثر بالسعر والتوفر والتسويق والأعراف والبيئة. لذلك توصي WHO بأدوات سكانية مثبتة للكحول والتبغ والنيكوتين إلى جانب تدخلات الأفراد. السياسة لا تلغي الاختيار الفردي؛ تغير البيئة التي يحدث فيها الاختيار وتقلل التعرض والضرر على مستوى السكان.'),
      jsonb_build_object('question','ماذا أفعل إذا اكتشفت أن ابني أو ابنتي بدأ الاستخدام؟','answer','تجنب تحويل اللحظة إلى تحقيق فقط. افهم ما حدث وتكراره والسياق، تحقق من السلامة والمخاطر المباشرة، حافظ على حوار واضح، واطلب تقييمًا مهنيًا إذا تكرر الاستخدام أو ظهر ضرر أو أعراض نفسية أو استخدام متعدد. كلما ارتفعت الشدة ينتقل المسار من الوقاية إلى العلاج المناسب.')
    ))
  ));

  select string_agg(case b->>'type' when 'paragraph' then b->>'text' when 'heading' then b->>'text' when 'list' then (select string_agg(value,E'\n') from jsonb_array_elements_text(b->'items')) when 'faq' then (select string_agg((x->>'question')||E'\n'||(x->>'answer'),E'\n\n') from jsonb_array_elements(b->'items') x) else '' end,E'\n\n') into v_text from jsonb_array_elements(v_body->'blocks') b;

  insert into public.content(content_type,slug,title,excerpt,body_json,body_text,sector_id,category_id,audience,status,seo_title,seo_description,canonical_url,robots_index,robots_follow,schema_json,published_at,search_aliases,primary_keyword,secondary_keywords,semantic_terms,search_intent,author_display_name,last_reviewed_at,references_json,medical_disclaimer)
  values(
    'article','addiction-prevention-reference','الوقاية من الإدمان والتدخل المبكر: ما الذي يعمل عبر الأسرة والمدرسة والمجتمع؟','مرجع عربي قائم على الدليل يشرح الوقاية النمائية من اضطرابات استخدام المواد، دور الأسرة والمدرسة والسياسات والتدخل المبكر، وما لا تكفيه حملات التخويف، وكيف تُقاس النتائج.',v_body,v_text,v_sector,v_category,array['الأسرة','المدربون وميسرو الأقران','المجتمع والمؤسسات','المختصون','الشخص المتأثر بالإدمان']::text[],'draft','الوقاية من الإدمان والتدخل المبكر | روافد','دليل عربي للوقاية من الإدمان: ما الذي يعمل عبر الأسرة والمدرسة والمجتمع والسياسات، وكيف نبني التدخل المبكر ونقيس النتائج دون تخويف أو وصم وبأسس علمية.','/content/addiction-prevention-reference/',true,true,
    jsonb_build_object(
      'content_contract_version',6,'disclaimer_url','/disclaimer','disclaimer_label','إخلاء المسؤولية والتنبيهات','taxonomy_reviewed',true,'classification_confidence',0.99,
      'classification_rationale','هذه الصفحة تنتمي إلى قطاع الإدمان والتعافي ومسار الوقاية والتدخل المبكر لأنها تنظم الوقاية عبر مراحل النمو والأسرة والمدرسة والمجتمع والسياسات ثم تربط المؤشرات المبكرة بخدمات التقييم والعلاج، مع تمييز التدخلات القائمة على الدليل عن حملات المعلومات أو التخويف المنفردة.',
      'rewrite_method','evidence-led-rewrite','originality_report',jsonb_build_object('passed',true,'method','manual-evidence-structure-and-duplication-review','duplicate_page_created',false),
      'source_versions_reviewed',jsonb_build_array('UNODC-WHO Prevention Standards 2018','UNODC Family Skills Compilation 2025','WHO SAFER progress report 2026','WHO SAFER technical framework','WHO MPOWER 2025-2026','WHO nicotine youth marketing 2026','WHO tobacco and nicotine factsheet 2026','WHO-UNODC Treatment Standards 2020'),
      'search_intent_questions',jsonb_build_array('كيف نقي المراهقين من الإدمان؟','ما أفضل طريقة للوقاية من المخدرات؟','هل تخويف الأطفال من المخدرات فعال؟','كيف أتحدث مع طفلي عن المخدرات؟','ما دور الأسرة في الوقاية من الإدمان؟','ما برامج الوقاية المدرسية الفعالة؟','ما علامات الحاجة إلى تدخل مبكر؟','هل فحص الطلاب عن تعاطي المواد مفيد؟','ما دور قوانين التبغ والكحول في الوقاية؟','كيف نقيس نجاح برنامج الوقاية من الإدمان؟'),
      'claim_source_map',jsonb_build_array(
